using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace GearLab {
 static class CadTests {
  static void SaveManifest(CadAssembly model,string file,int kind){var manifest=new {kind=kind,parts=model.Parts.Select(part=>new {id=part.Id,label=part.Label,role=part.Role,volume=part.Volume(),reference=part.Reference}).ToArray(),bounds=model.Bounds(),notes=model.Notes};ReleaseSupport.WriteText(file+".manifest.json",new JavaScriptSerializer().Serialize(manifest),Encoding.UTF8);}
  static void Render(CadAssembly model,string file,bool hide){using(var image=new Bitmap(1200,900))using(var g=Graphics.FromImage(image)){g.Clear(Color.FromArgb(248,250,252));g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;CadPreview.Draw(g,model,1200,900,-.65,.8,1,false,hide);image.Save(file);}}
  public static int Run(string folder){Directory.CreateDirectory(folder);try{var report=new StringBuilder();foreach(int kind in new[]{0,1,2,3}){var p=Engine.Starter(kind);var r=Engine.Calculate(p);var model=CadBuilder.Build(r);if(!model.Valid)throw new Exception("CAD kind "+kind+": "+string.Join(";",model.Errors));string file=Path.Combine(folder,"model-"+kind);StepExport.Write(model,file+".step");FullDrawingExport.Write(model,"svg",file+".svg");FullDrawingExport.Write(model,"dxf",file+".dxf");FullDrawingExport.Csv(model,file+".csv");ReleaseSupport.WriteText(file+".gear.json",ReleaseSupport.Serialize(p),Encoding.UTF8);SaveManifest(model,file,kind);Render(model,file+".png",false);Render(model,file+"-inside.png",true);report.AppendLine("CAD "+kind+": "+model.Parts.Count+" bodies; positive volume; STEP, SVG, DXF, CSV generated.");}
   var train=Engine.Starter(3);train.Ratio=60;train.Overall=222.82;Engine.FitOverall(train);var result=Engine.Calculate(train);var assembly=CadBuilder.Build(result);if(!assembly.Valid)throw new Exception(string.Join(";",assembly.Errors));StepExport.Write(assembly,Path.Combine(folder,"planet-60.step"));FullDrawingExport.Csv(assembly,Path.Combine(folder,"planet-60.csv"));
   SaveManifest(assembly,Path.Combine(folder,"planet-60"),3);Render(assembly,Path.Combine(folder,"planet-60-inside.png"),true);ReleaseSupport.WriteText(Path.Combine(folder,"planet-60.gear.json"),ReleaseSupport.Serialize(train),Encoding.UTF8);
   var standard=Engine.Starter(0);standard.RingOutput=false;Engine.FitOverall(standard);var sm=CadBuilder.Build(Engine.Calculate(standard));if(!sm.Valid)throw new Exception("Standard cycloid: "+string.Join(";",sm.Errors));StepExport.Write(sm,Path.Combine(folder,"standard-cycle.step"));SaveManifest(sm,Path.Combine(folder,"standard-cycle"),0);Render(sm,Path.Combine(folder,"standard-cycle-inside.png"),true);report.AppendLine("Standard cycloid: "+sm.Parts.Count+" bodies.");
   for(int kind=0;kind<4;kind++)for(int preset=1;preset<=4;preset++){var cp=Engine.Starter(kind);Engine.SetPreset(cp,preset);Engine.FitOverall(cp);var cm=CadBuilder.Build(Engine.Calculate(cp));if(!cm.Valid)throw new Exception("CAD preset "+kind+"/"+preset+": "+string.Join(";",cm.Errors));}report.AppendLine("PASS 16 CAD type/preset combinations.");
   FullDrawingExport.Calibration(Path.Combine(folder,"calibration_10mm.svg"));report.AppendLine("CAD multistage 60: "+assembly.Parts.Count+" bodies; calibration square 10 mm.");using(var form=new MainForm(new TestDialogs()))form.CadUiRegression(folder,report);ReleaseSupport.WriteText(Path.Combine(folder,"cad-results.txt"),report.ToString(),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"cad-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
